public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Precompute substring sets for each string
    List<Set<String>> substringSets = new ArrayList<>(strings.size());
    for (String s : strings) {
        if (s == null) {
            return 0; // Treat null string as empty, thus no substrings
        }
        Set<String> set = new HashSet<>();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                set.add(s.substring(i, j));
            }
        }
        substringSets.add(set);
    }

    // Generate candidate substrings from the first string
    String first = strings.get(0);
    int maxLen = 0;
    int len = first.length();
    for (int i = 0; i < len; i++) {
        for (int j = i + 1; j <= len; j++) {
            String candidate = first.substring(i, j);
            int candLen = j - i;
            if (candLen <= maxLen) { // already shorter or equal to best, skip
                continue;
            }
            String reverse = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (Set<String> set : substringSets) {
                if (!(set.contains(candidate) || set.contains(reverse))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                maxLen = candLen;
            }
        }
    }
    return maxLen;
}

public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Build substring sets for all strings
    java.util.List<java.util.Set<String>> sets = new java.util.ArrayList<>();
    for (String s : strings) {
        if (s == null) {
            s = "";
        }
        java.util.Set<String> subSet = new java.util.HashSet<>();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                subSet.add(s.substring(i, j));
            }
        }
        sets.add(subSet);
    }

    // Use the first string as the source of candidates
    String first = strings.get(0);
    if (first == null) {
        first = "";
    }
    int firstLen = first.length();
    java.util.Set<String> seen = new java.util.HashSet<>();

    for (int len = firstLen; len >= 1; len--) {
        for (int start = 0; start + len <= firstLen; start++) {
            String candidate = first.substring(start, start + len);
            if (!seen.add(candidate)) {
                continue; // skip duplicates
            }
            String rev = new java.lang.StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (java.util.Set<String> subSet : sets) {
                if (!(subSet.contains(candidate) || subSet.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the first non-null, non-empty string to generate candidates
    String first = null;
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s != null && !s.isEmpty()) {
            if (first == null) {
                first = s;
            }
            if (s.length() < minLen) {
                minLen = s.length();
            }
        }
    }
    if (first == null || minLen == Integer.MAX_VALUE) {
        return 0;
    }

    // Iterate over possible lengths from largest to smallest
    for (int len = minLen; len >= 1; len--) {
        // Collect all unique substrings of length len from the first string
        java.util.Set<String> candidates = new java.util.HashSet<>();
        for (int i = 0; i <= first.length() - len; i++) {
            candidates.add(first.substring(i, i + len));
        }

        // Test each candidate against all strings
        for (String candidate : candidates) {
            String rev = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (s == null || s.isEmpty()) {
                    ok = false;
                    break;
                }
                if (!s.contains(candidate) && !s.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }

    return 0; // No common substring found
}

public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // If any string is null treat the result as 0
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
    }
    // Choose the shortest string as base for generating substrings
    String base = strings.get(0);
    for (String s : strings) {
        if (s.length() < base.length()) {
            base = s;
        }
    }
    int baseLen = base.length();
    // Iterate lengths from longest to shortest
    for (int len = baseLen; len >= 1; len--) {
        for (int start = 0; start + len <= baseLen; start++) {
            String sub = base.substring(start, start + len);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean foundInAll = true;
            for (String s : strings) {
                if (!(s.contains(sub) || s.contains(rev))) {
                    foundInAll = false;
                    break;
                }
            }
            if (foundInAll) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Handle null strings as empty
    for (int i = 0; i < strings.size(); i++) {
        if (strings.get(i) == null) {
            strings.set(i, "");
        }
    }

    // Find the minimum length among all strings to limit search
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        minLen = Math.min(minLen, s.length());
    }
    if (minLen == 0) {
        return 0;
    }

    String base = strings.get(0);
    // Try lengths from minLen down to 1
    for (int len = minLen; len >= 1; len--) {
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i <= base.length() - len; i++) {
            candidates.add(base.substring(i, i + len));
        }

        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(cand) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }

    return 0; // no common substring longer than 0 found
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int deposits = 0;
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                // Start a new deposit
                deposits++;
                // BFS/DFS stack
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0], cc = pos[1];
                    for (int dir = 0; dir < 8; dir++) {
                        int nr = cr + dx[dir];
                        int nc = cc + dy[dir];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return deposits;
}

