                    int top = 0;
                    stack[top++] = i * cols + j;
                    visited[i][j] = true;
                    while (top > 0) {
                        int idx = stack[--top];
                        int x = idx / cols;
                        int y = idx % cols;
                        for (int d = 0; d < 8; d++) {
                            int nx = x + dx[d];
                            int ny = y + dy[d];
                            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols &&
                                grid[nx][ny] == '@' && !visited[nx][ny]) {
