                    int nc = curC + dCol[dir];
                    if (nr < 0 || nr >= rows || nc < 0) continue;
                    if (grid[nr] == null || nc >= grid[nr].length) continue;
                    if (visited[nr][nc]) continue;
                    if (grid[nr][nc] == '@') {
                        visited[nr][nc] = true;
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
        }
    }

    return depositCount;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1; // No triangles divides the plane into a single region
    }
    long regions = 3L * N * (N - 1) + 2;
    // Clamp to Integer.MAX_VALUE in case of overflow
    if (regions > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    }
    return (int) regions;
}

