public static int maxRegions(int N) {
    // Handle non‑positive input: no triangles mean one whole plane region.
    if (N <= 0) {
        return 1;
    }
    // The maximum number of regions created by N triangles is:
    // 2 + 3 * N * (N - 1).
    long regions = 2L + 3L * N * (N - 1);
    if (regions > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Result exceeds integer range");
    }
    return (int) regions;
}

