public static int countDoubles(int[] numbers) {
    if (numbers == null) {
        return 0;
    }
    java.util.HashSet<Integer> set = new java.util.HashSet<>();
    for (int n : numbers) {
        set.add(n);
    }
    int count = 0;
    for (int n : numbers) {
        long targetLong = (long) n * 2;
        // Ignore overflow and self‑doubling
        if (targetLong == n || targetLong < Integer.MIN_VALUE || targetLong > Integer.MAX_VALUE) {
            continue;
        }
        int target = (int) targetLong;
        if (set.contains(target)) {
            count++;
        }
    }
    return count;
}

public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    int count = 0;
    for (int i = 0; i < numbers.length; i++) {
        for (int j = 0; j < numbers.length; j++) {
            if (i == j) {
                continue;
            }
            if (numbers[i] == 2 * numbers[j]) {
                count++;
                break; // Found a partner, no need to check further for this element
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        // Basic validation
        if (n <= 0 || start == null || end == null || start.length == 0 || end.length == 0) {
            return "cannot be travelled";
        }

        // Assume the first element represents the unique node id
        int startNode = start[0];
        int endNode = end[0];

        if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
            return "cannot be travelled";
        }

        // Build adjacency list
        java.util.List<java.util.List<Integer>> adj = new java.util.ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new java.util.ArrayList<>());
        }

        if (paths != null) {
            for (int[] p : paths) {
                if (p != null && p.length == 2) {
                    int u = p[0];
                    int v = p[1];
                    if (u >= 0 && u < n && v >= 0 && v < n) {
                        adj.get(u).add(v);
                        adj.get(v).add(u); // assuming undirected graph
                    }
                }
            }
        }

        // Breadth‑first search to check connectivity
        boolean[] visited = new boolean[n];
        java.util.Deque<Integer> queue = new java.util.ArrayDeque<>();
        queue.add(startNode);
        visited[startNode] = true;

        while (!queue.isEmpty()) {
            int current = queue.poll();
            if (current == endNode) {
                return "can be travelled";
            }
            for (int neighbor : adj.get(current)) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.add(neighbor);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        // Any exception is treated as an indication that travel is impossible
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length == 0 || start.length != end.length) {
        return "cannot be travelled";
    }
    int dims = start.length;
    int totalNodes = 1;
    for (int i = 0; i < dims; i++) {
        totalNodes *= n;
    }
    java.util.List<Integer>[] adjacency = new java.util.ArrayList[totalNodes];
    for (int i = 0; i < totalNodes; i++) {
        adjacency[i] = new java.util.ArrayList<>();
    }
    if (paths != null) {
        for (int[] edge : paths) {
            if (edge == null || edge.length != 2) continue;
            int a = edge[0];
            int b = edge[1];
            if (a < 0 || a >= totalNodes || b < 0 || b >= totalNodes) continue;
            adjacency[a].add(b);
            adjacency[b].add(a);
        }
    }
    int startIdx = 0;
    int pow = 1;
    for (int i = 0; i < dims; i++) {
        int val = start[i];
        if (val < 0 || val >= n) return "cannot be travelled";
        startIdx += val * pow;
        pow *= n;
    }
    pow = 1;
    int endIdx = 0;
    for (int i = 0; i < dims; i++) {
        int val = end[i];
        if (val < 0 || val >= n) return "cannot be travelled";
        endIdx += val * pow;
        pow *= n;
    }
    if (startIdx == endIdx) return "can be travelled";
    java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();
    boolean[] visited = new boolean[totalNodes];
    queue.offer(startIdx);
    visited[startIdx] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        for (int next : adjacency[cur]) {
            if (!visited[next]) {
                if (next == endIdx) return "can be travelled";
                visited[next] = true;
                queue.offer(next);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0 || start == null || end == null || paths == null) {
            return "cannot be travelled";
        }
        if (start.length != n || end.length != n) {
            return "cannot be travelled";
        }
        // Helper to convert coordinate array to a unique string key
        java.util.function.Function<int[], String> toKey = arr -> java.util.Arrays.toString(arr);

        String startKey = toKey.apply(start);
        if (java.util.Arrays.equals(start, end)) {
            return "can be travelled";
        }
        String endKey = toKey.apply(end);

        // Build adjacency list
        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
        for (int[] p : paths) {
            // Expect each path entry to consist of two coordinates, each of length n.
            if (p == null || p.length != 2 * n) {
                continue; // skip malformed entry
            }
            int[] a = new int[n];
            int[] b = new int[n];
            System.arraycopy(p, 0, a, 0, n);
            System.arraycopy(p, n, b, 0, n);
            String aKey = toKey.apply(a);
            String bKey = toKey.apply(b);
            graph.computeIfAbsent(aKey, k -> new java.util.ArrayList<>()).add(bKey);
            graph.computeIfAbsent(bKey, k -> new java.util.ArrayList<>()).add(aKey); // assuming undirected
        }

        // BFS to check connectivity
        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        queue.add(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String cur = queue.poll();
            java.util.List<String> neighbors = graph.getOrDefault(cur, java.util.Collections.emptyList());
            for (String nb : neighbors) {
                if (visited.contains(nb)) {
                    continue;
                }
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.add(nb);
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

