public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0) {
        return false;
    }
    if (k <= 0) { // divisor must be positive
        return false;
    }
    if (arr.length % 2 != 0) { // must form n/2 pairs
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = Math.floorMod(num, k); // ensure positive remainder
        freq[rem]++;
    }
    // Remainder 0 must pair among themselves
    if (freq[0] % 2 != 0) {
        return false;
    }
    // For the rest of the remainders
    for (int r = 1; r <= (k - 1) / 2; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    // If k is even, remainder k/2 must pair among themselves
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    return true;
}

