public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k;
        }
        freq[r]++;
    }

    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }

    for (int r = 1; r < k; r++) {
        int complement = (k - r) % k;
        if (r == complement) { // e.g., k even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else if (r < complement) {
            if (freq[r] != freq[complement]) {
                return false;
            }
        }
    }

    return true;
}

