        for (int[] e : edges) {
            if (e == null || e.length < 2) continue;
            int u = e[0], v = e[1];
            if (u >= 0 && u < n && v >= 0 && v < n) {
                graph[u].add(v);
                graph[v].add(u);
            }
        }
    }

