public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    // Count occurrences of each Unicode character (code point <= 65535).
    int[] count = new int[65536];
    for (int i = 0; i < s.length(); i++) {
        count[s.charAt(i)]++;
    }

    StringBuilder result = new StringBuilder(s.length());
    int remaining = s.length();

    while (remaining > 0) {
        // Ascending phase: pick smallest to largest distinct characters.
        int lastIdx = -1; // sentinel for “no last character”
        for (int i = 0; i < 65536; i++) {
            if (count[i] > 0 && i > lastIdx) {
                result.append((char) i);
                count[i]--;
                remaining--;
                lastIdx = i;
            }
        }

        // Descending phase: pick largest to smallest distinct characters.
        lastIdx = 65536; // sentinel larger than any valid index
        for (int i = 65535; i >= 0; i--) {
            if (count[i] > 0 && i < lastIdx) {
                result.append((char) i);
                count[i]--;
                remaining--;
                lastIdx = i;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int total = s.length();
    // Frequency array for extended ASCII characters (0-255)
    int[] freq = new int[256];
    for (int i = 0; i < s.length(); i++) {
        freq[s.charAt(i)]++;
    }
    StringBuilder result = new StringBuilder(total);
    while (total > 0) {
        // Step 1: pick the smallest remaining character
        int last = -1;
        for (int i = 0; i < 256; i++) {
            if (freq[i] > 0) {
                last = i;
                break;
            }
        }
        if (last == -1) {
            break;
        }
        result.append((char) last);
        freq[last]--;
        total--;

        // Step 2: keep picking the next smallest character greater than the last one
        while (true) {
            int next = -1;
            for (int i = last + 1; i < 256; i++) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            result.append((char) next);
            freq[next]--;
            total--;
            last = next;
        }

        // Step 4: pick the largest remaining character
        if (total == 0) {
            break;
        }
        int lastDesc = -1;
        for (int i = 255; i >= 0; i--) {
            if (freq[i] > 0) {
                lastDesc = i;
                break;
            }
        }
        if (lastDesc == -1) {
            break;
        }
        result.append((char) lastDesc);
        freq[lastDesc]--;
        total--;

        // Step 5: keep picking the next largest character smaller than the last one
        while (true) {
            int next = -1;
            for (int i = lastDesc - 1; i >= 0; i--) {
                if (freq[i] > 0) {
                    next = i;
                    break;
                }
            }
            if (next == -1) {
                break;
            }
            result.append((char) next);
            freq[next]--;
            total--;
            lastDesc = next;
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int maxK = n / 2;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[maxK + 1];
    for (int i = 0; i <= maxK; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        // iterate k from maxK down to 1
        for (int k = Math.min(maxK, n); k >= 1; k--) {
            java.util.HashSet<Integer> prevSet = dp[k - 1];
            if (!prevSet.isEmpty()) {
                java.util.Iterator<Integer> it = prevSet.iterator();
                while (it.hasNext()) {
                    int prevSum = it.next();
                    dp[k].add(prevSum + num);
                }
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((long) totalSum * k % n != 0L) {
            continue;
        }
        int target = (int) ((long) totalSum * k / n);
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

