    java.util.Set<Integer>[] sums = new java.util.HashSet[maxK + 1];
    for (int i = 0; i <= maxK; i++) {
        sums[i] = new java.util.HashSet<>();
    }
    sums[0].add(0);
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            for (int s : sums[k - 1]) {
                sums[k].add(s + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        long targetSumLong = (long) totalSum * k;
        if (targetSumLong % n == 0) {
            int target = (int) (targetSumLong / n);
            if (sums[k].contains(target)) {
                return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int m = n / 2;
    int secondSize = n - m;
    // Prepare second half subsets sums grouped by subset size
    @SuppressWarnings("unchecked")
    Set<Integer>[] secondSets = new HashSet[secondSize + 1];
    for (int i = 0; i <= secondSize; i++) {
        secondSets[i] = new HashSet<>();
    }
    // Enumerate all subsets of the second half
    for (int mask = 0; mask < (1 << secondSize); mask++) {
        int sum = 0;
        int cnt = 0;
        for (int j = 0; j < secondSize; j++) {
            if (((mask >> j) & 1) == 1) {
                sum += nums[m + j];
                cnt++;
            }
        }
        secondSets[cnt].add(sum);
    }
    // Check each possible subset size k
    for (int k = 1; k <= n / 2; k++) {
        // totalSum * k must be divisible by n to have integer target sum
        if ((totalSum * k) % n != 0) {
            continue;
        }
        int target = (totalSum * k) / n;
        // Enumerate all subsets of the first half
        for (int mask = 0; mask < (1 << m); mask++) {
            int sum = 0;
            int cnt = 0;
            for (int j = 0; j < m; j++) {
                if (((mask >> j) & 1) == 1) {
                    sum += nums[j];
                    cnt++;
                }
            }
            if (cnt > k) {
                continue;
            }
            int remainCnt = k - cnt;
            if (remainCnt < 0 || remainCnt > secondSize) {
                continue;
            }
            int needed = target - sum;
            if (secondSets[remainCnt].contains(needed)) {
                return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    try {
        int n = cost.length;
        int prev = 0; // dp[0]
        int curr = 0; // dp[1]
        for (int i = 2; i <= n; i++) {
            int step1 = curr + cost[i - 1];
            int step2 = prev + cost[i - 2];
            int next = Math.min(step1, step2);
            prev = curr;
            curr = next;
        }
        return curr;
    } catch (Exception e) {
        // In case of unexpected errors, return 0 as a safe default
        return 0;
    }
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start directly from step 1 (the top), so no cost is incurred.
        return 0;
    }
    int prev2 = cost[0]; // Cost to reach step 0
    int prev1 = cost[1]; // Cost to reach step 1
    for (int i = 2; i < n; i++) {
        int curr = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return 0; // can start on the top without any cost
    }
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    int prev1 = 0; // cost to reach step i-1
    int prev2 = 0; // cost to reach step i-2

    for (int i = 2; i <= n; i++) {
        int payFromPrev = prev1 + cost[i - 1];
        int payFromPrevPrev = prev2 + cost[i - 2];
        int current = Math.min(payFromPrev, payFromPrevPrev);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    // dp[0] and dp[1] represent the minimal cost to reach step 0 and step 1 respectively.
    int prev2 = 0; // cost to reach step 0
    int prev1 = 0; // cost to reach step 1
    if (n == 1) {
        // We can start at step 1 (index 1) without paying any cost.
        // Alternatively, we could pay cost[0] to start at step 0.
        // The minimum of these two options is the answer.
        return Math.min(prev1, prev2);
    }
    for (int i = 2; i <= n; i++) {
        int idx = i - 1; // actual index in cost array
        int current = cost[idx] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

