    int required = 1 << k;
    java.util.Set<Integer> seen = new java.util.HashSet<>(required);
    int val = 0;
    for (int i = 0; i < k; i++) {
        val = (val << 1) | (s.charAt(i) - '0');
    }
    seen.add(val);
