    try {
        if (s == null || k <= 0) {
            return false;
        }
        int n = s.length();
        if (n < k) {
            return false;
        }

        // For small k (<=30) we can use a boolean array for speed.
        if (k < 31) {
            int totalCodes = 1 << k;
            boolean[] seen = new boolean[totalCodes];
            int mask = totalCodes - 1;
            int val = 0;
