public int minOperations(int n) {
    // Validate input
    if (n <= 0) {
        throw new IllegalArgumentException("Array length must be positive");
    }

    // Compute ceil(n/2) as (n+1)/2 for integers
    long m = (n + 1L) / 2L;   // Surplus threshold index count
    long k = n - m;           // Number of surplus elements

    long operations = k * m;  // Total units to transfer

    // The result fits within int for typical constraints
    return (int)operations;
}

public int minOperations(int n) {
    if (n <= 1) {
        return 0;
    }
    long target = n;
    // Start index of elements greater than target
    long a = ((n - 1) / 2) + 1;   // floor((n-1)/2) + 1
    long b = n - 1;
    if (a > b) {
        return 0;
    }
    long len = b - a + 1;
    long sumI = (a + b) * len / 2;          // Sum of indices from a to b
    long ops = 2 * sumI + len - target * len; // Total surplus
    return (int) ops;
}

public int minOperations(int n) {
    if (n <= 1) {
        return 0;
    }
    // Ceil of n/2
    int t = (n + 1) / 2;
    int m = n - t;
    long ops = (long) t * m; // use long to avoid intermediate overflow
    if (ops > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Result exceeds int range");
    }
    return (int) ops;
}

