        long next = (long) fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add((int) next);
    }

    int count = 0;
    while (k > 0) {
        // Find the largest Fibonacci number <= k
        int idx = fibs.size() - 1;
        while (fibs.get(idx) > k) {
            idx--;
        }
        k -= fibs.get(idx);
        count++;
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    java.util.Collections.sort(factors);
    return k <= factors.size() ? factors.get(k - 1) : -1;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) return -1;
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int div = n / i;
            if (div != i) {
                factors.add(div);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) return -1;
    return factors.get(k - 1);
}

