    }
    int sqrtN = (int) Math.sqrt(n);
    int[] small = new int[sqrtN + 1];
    int[] large = new int[sqrtN + 1];
    int smallCnt = 0;
    int largeCnt = 0;
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            small[smallCnt++] = i;
            int other = n / i;
            if (other != i) {
                large[largeCnt++] = other;
            }
        }
    }
    int total = smallCnt + largeCnt;
    if (k > total) {
        return -1;
    }
    if (k <= smallCnt) {
        return small[k - 1];
    } else {
        int idxInLarge = k - smallCnt; // 1‑based index within the ascending large factors
        // large array stores factors in descending order
        return large[largeCnt - idxInLarge];
    }
}

