public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    char[] stack = new char[n];
    int top = 0;
    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (top > 0) {
            char prev = stack[top - 1];
            if (Math.abs(c - prev) == 32) { // 'a' vs 'A', 'b' vs 'B', etc.
                top--; // remove the matching pair
                continue;
            }
        }
        stack[top++] = c;
    }
    return new String(stack, 0, top);
}

