        int len = stack.length();
        if (len > 0 && Math.abs(c - stack.charAt(len - 1)) == 32) {
            stack.deleteCharAt(len - 1); // remove the opposing pair
        } else {
            stack.append(c); // push current character
        }
    }
    return stack.toString();
}

