        }
        if ("../".equals(log)) {
            depth = Math.max(0, depth - 1);
        } else if ("./".equals(log)) {
            // stay in the same directory
            continue;
        } else if (log.endsWith("/")) {
            // assume it's a directory entry
            depth++;
        } else {
            // If the log doesn't match expected patterns, ignore it
            continue;
        }
    }
    return depth;
}

