public String getSmallestString(int n, int k) {
    // Validate input: minimum sum is n (all 'a'), maximum sum is 26*n (all 'z')
    if (k < n || k > 26 * n) {
        return "";
    }
    char[] chars = new char[n];
    // Start with all 'a'
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    int remaining = k - n; // total additional value needed beyond all 'a's
    // Distribute the remaining value from the end to maximize lexicographic ordering
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can increase up to 25 (a->z)
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int minSum = n;          // all characters 'a' -> sum = n
    int maxSum = 26 * n;     // all characters 'z' -> sum = 26*n
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("k out of valid range");
    }

    char[] chars = new char[n];
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }

    int diff = k - minSum;   // additional value needed beyond all 'a's
    for (int i = n - 1; i >= 0 && diff > 0; i--) {
        int add = Math.min(25, diff);   // up to 25 because 'a' is 1, 'z' is 26
        chars[i] = (char) ('a' + add);
        diff -= add;
    }

    return new String(chars);
}

