    // Initialize all positions with 'a' (value 1)
    for (int i = 0; i < n; i++) result[i] = 'a';
    int remaining = k - n; // amount of value still to distribute
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can increase at most 25 (from 'a' to 'z')
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) throw new IllegalArgumentException("Length n must be positive.");
    if (k < n || k > 26L * n) throw new IllegalArgumentException("k out of valid range.");
    StringBuilder sb = new StringBuilder(n);
    for (int i = 0; i < n; i++) sb.append('a');
    int remaining = (int)(k - n);
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        sb.setCharAt(i, (char)('a' + add));
        remaining -= add;
    }
    return sb.toString();
}

