public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    TreeSet<Integer> steppingSet = new TreeSet<>();

    // Include 0 if within range
    if (low <= 0 && high >= 0) {
        steppingSet.add(0);
    }

    // Start BFS from digits 1 to 9 (exclude 0 to avoid duplicates)
    for (int start = 1; start <= 9; start++) {
        if (start > high) {
            break;
        }

        Queue<Long> queue = new LinkedList<>();
        queue.offer((long) start);

        while (!queue.isEmpty()) {
            long num = queue.poll();
            if (num > high) {
                continue;
            }

            if (num >= low) {
                steppingSet.add((int) num);
            }

            int lastDigit = (int) (num % 10);

            if (lastDigit > 0) {
                long child = num * 10 + (lastDigit - 1);
                if (child <= high) {
                    queue.offer(child);
                }
            }

            if (lastDigit < 9) {
                long child = num * 10 + (lastDigit + 1);
                if (child <= high) {
                    queue.offer(child);
                }
            }
        }
    }

    result.addAll(steppingSet);
    return result;
}

