public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long high = n / (factor * 10);
        long cur = (n / factor) % 10;
        long low = n % factor;
        count += high * factor;
        if (cur == 1) {
            count += low + 1;
        } else if (cur > 1) {
            count += factor;
        }
    }
    return (int) count;
}

