    // Remember if the number is negative
    boolean isNegative = n < 0;
    long value = Math.abs((long) n); // use long to avoid overflow for Integer.MIN_VALUE

    // Build the formatted number from the end two‑ways: tens
    int count = 0;
    while (value > 0) {
        int digit = (int) (value % 10);
        result.append(digit);
        value /= 10;
        count++;

        // Insert a dot after every three digits, except at the very end
        if (count % 3 == 0 && value > 0) {
            result.append('.');
        }
    }

    // Restore the original order
    result.reverse();

    // Prepend the negative sign if needed
    if (isNegative) {
        result.insert(0, '-');
    }

    return result.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long absVal = Math.abs((long) n);
    String s = Long.toString(absVal);
    StringBuilder sb = new StringBuilder();
    int len = s.length();
    for (int i = 0; i < len; i++) {
        sb.append(s.charAt(i));
        int remaining = len - i - 1;
        if (remaining > 0 && remaining % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

