public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    int[] arr = A.clone();
    java.util.Arrays.sort(arr);

    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = arr[i] + arr[j];
            double sqrt = Math.sqrt(sum);
            if (sqrt == Math.floor(sqrt)) can[i][j] = true;
        }
    }

    boolean[] used = new boolean[n];
    int[] count = new int[1];
    for (int i = 0; i < n; i++) {
        if (i > 0 && arr[i] == arr[i - 1]) continue;
        used[i] = true;
        dfs(arr, can, used, i, 1, count);
        used[i] = false;
    }
    return count[0];
}

private static void dfs(int[] arr, boolean[][] can, boolean[] used, int last, int depth, int[] count) {
    int n = arr.length;
    if (depth == n) {
        count[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (i > 0 && arr[i] == arr[i - 1] && !used[i - 1]) continue;
        if (can[last][i]) {
            used[i] = true;
            dfs(arr, can, used, i, depth + 1, count);
            used[i] = false;
        }
    }
}

public static int squarePermutations(int[] A) {
