    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    int maxVal = 0;
    for (int num : A) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
        if (num > maxVal) maxVal = num;
    }

    // Precompute perfect squares up to 2*maxVal
    int maxSum = 2 * maxVal;
    java.util.HashSet<Integer> sqSet = new java.util.HashSet<>();
    for (int i = 0; i * i <= maxSum; i++) {
        sqSet.add(i * i);
    }

    return dfs(-1, freq, sqSet);
}

private static int dfs(int prev, java.util.Map<Integer, Integer> freq, java.util.HashSet<Integer> sqSet) {
    // If all numbers used
    boolean allUsed = true;
    for (int cnt : freq.values()) {
        if (cnt > 0) {
            allUsed = false;
            break;
        }
    }
    if (allUsed) return 1;

    int total = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        int num = entry.getKey();
        int cnt = entry.getValue();
        if (cnt == 0) continue;
        if (prev != -1 && !sqSet.contains(prev + num)) continue;

        // Use this number
        freq.put(num, cnt - 1);
        total += dfs(num, freq, sqSet);
        freq.put(num, cnt); // backtrack
    }
    return total;
}

