}

private static int backtrack(int prevIndex, int depth, int[] A, boolean[] used, int n) {
    if (depth == n) {
        return 1;
    }
    int total = 0;
    for (int i = 0; i < n; i++) {
        if (used[i]) {
            continue;
        }
        // Skip duplicate values at the same depth
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) {
            continue;
        }
        if (prevIndex == -1 || isPerfectSquare(A[prevIndex] + A[i])) {
            used[i] = true;
            total += backtrack(i, depth + 1, A, used, n);
            used[i] = false;
        }
    }
    return total;
}

private static boolean isPerfectSquare(int sum) {
    int sqrt = (int) Math.sqrt(sum);
    return sqrt * sqrt == sum;
}

