public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = Math.max(0, sum - n + 1);
        int endRow = Math.min(m - 1, sum);
        if (sum % 2 == 0) { // even sum: traverse from bottom to top
            for (int i = endRow; i >= startRow; i--) {
                int j = sum - i;
                result[index++] = mat[i][j];
            }
        } else { // odd sum: traverse from top to bottom
            for (int i = startRow; i <= endRow; i++) {
                int j = sum - i;
                result[index++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    // Handle null or empty matrix
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int idx = 0;
    for (int s = 0; s <= rows + cols - 2; s++) {
        if (s % 2 == 0) {
            // Even diagonal: traverse from bottom-left to top-right
            int i = Math.min(s, rows - 1);
            int j = s - i;
            while (i >= 0 && j < cols) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            // Odd diagonal: traverse from top-right to bottom-left
            int j = Math.min(s, cols - 1);
            int i = s - j;
            while (j >= 0 && i < rows) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

