                result[index++] = mat[r][c];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    // Only positive integers allowed; otherwise return -1
    if (n <= 0) {
        return -1;
    }

    // Convert the integer to a character array of its digits
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Find the longest non-increasing suffix
    int pivot = -1;
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            pivot = i;
            break;
        }
    }

    // If no pivot, digits are in non-increasing order – no greater permutation
    if (pivot == -1) {
        return -1;
    }

    // Find the rightmost successor to the pivot in the suffix
    int successor = -1;
    for (int i = len - 1; i > pivot; i--) {
        if (digits[i] > digits[pivot]) {
            successor = i;
            break;
        }
    }

    // Swap pivot and successor
    char temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;

    // Reverse the suffix starting at pivot + 1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to an integer, handling overflow
    try {
        int result = Integer.parseInt(new String(digits));
        // Ensure the result is strictly greater than the original number
        if (result > n) {
            return result;
        } else {
            return -1;
        }
    } catch (NumberFormatException e) {
        // Integer overflow or invalid number
        return -1;
    }
}

