public static int findSmallestInteger(int n) {
    // n must be a positive integer
    if (n <= 0) {
        return -1;
    }

    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the longest non‑increasing suffix
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no pivot, n is the highest permutation
    if (i < 0) {
        return -1;
    }

    // Step 2: Find the rightmost successor to the pivot in the suffix
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap pivot with successor
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Reverse the suffix
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Convert back to integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // In practice this should not happen because permutations of n fit in int
        return -1;
    }
}

