        dp[i] = (int) nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = (long) dp[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = (long) dp[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = (long) dp[i5] * 5;
        }
    }
    return dp[n - 1];
}

