public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) return result;
    int curr = 1;
    for (int i = 1; i <= n; i++) {
        result.add(curr);
        if ((long) curr * 10 <= n) {
            curr *= 10;
        } else {
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;
            }
            curr++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    Deque<Integer> stack = new ArrayDeque<>();
    // Initialize stack with the first level digits from 9 down to 1 (or up to n)
    for (int i = Math.min(9, n); i >= 1; i--) {
        stack.push(i);
    }
    while (!stack.isEmpty()) {
        int current = stack.pop();
        if (current > n) {
            continue;
        }
        result.add(current);
        // Push children of current node in reverse digit order to maintain lexicographical order
        for (int d = 9; d >= 0; d--) {
            long childLong = (long) current * 10 + d;
            if (childLong > n) {
                // No need to push numbers greater than n
                continue;
            }
            stack.push((int) childLong);
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    long cur = 1;
    for (int i = 0; i < n; i++) {
        result.add((int) cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) {
            cur += 1;
        } else {
            while (cur / 10 % 10 == 9) {
                cur /= 10;
            }
            cur = cur / 10 + 1;
        }
    }
    return result;
}

